import{_ as r,C as t,o as i,c as s,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/context-authority-20260918/approval-arguments.figure.en.svg",b=JSON.parse('{"title":"You approved the arguments. Did the tool execute the same ones?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"You approved the arguments. Did the tool execute the same ones?","date":"2026-09-18","published_date":"2026-09-18","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Are the arguments inspected by conditional approval the arguments ultimately executed by the function?","summary":"We ran the same six cases against OpenAI Agents Python v0.22.2 and v0.22.3 to see how defaults, coercion and validators affect the approval boundary.","cover":"/assets/context-authority-20260918/approval-arguments.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Pinned-version original-code comparison; boundaries stated in text","pageClass":"context-authority-article"},"headers":[],"relativePath":"en/research/2026-09-18-approval-saw-raw-tool-ran-prepared.md","filePath":"en/research/2026-09-18-approval-saw-raw-tool-ran-prepared.md","lastUpdated":1789700812000}'),c={name:"en/research/2026-09-18-approval-saw-raw-tool-ran-prepared.md"};function p(h,e,u,g,v,m){const o=t("ArticleCover"),n=t("ArticleTableScroll");return i(),s("div",null,[a(o,{image:"/assets/context-authority-20260918/approval-arguments.cover-v1.png",kicker:"Open-source engineering · Version comparison",title:"You approved the arguments. Did the tool execute the same ones?",summary:"Defaults, coercion, and validators can change the actual action after a policy sees the request.",version:"2026-09-18",languageHref:"/zh/research/2026-09-18-approval-saw-raw-tool-ran-prepared",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=d('<h1 id="you-approved-the-arguments-did-the-tool-execute-the-same-ones" tabindex="-1">You approved the arguments. Did the tool execute the same ones? <a class="header-anchor" href="#you-approved-the-arguments-did-the-tool-execute-the-same-ones" aria-label="Permalink to &quot;You approved the arguments. Did the tool execute the same ones?&quot;">​</a></h1><p>An agent is about to call a tool. The approval policy sees an empty object, <code>{}</code>, finds no protected target, and allows the call.</p><p>The function then receives <code>target=&quot;protected&quot;</code>.</p><p>The agent did not swap the argument. An ordinary validation step supplied a default. The same separation can happen when a string <code>&quot;1&quot;</code> becomes integer <code>1</code>, or when an application validator normalizes <code>PROD</code> to <code>prod</code>.</p><p>That creates a precise governance question: <strong>is the object being approved the object that will actually be executed?</strong></p><h2 id="why-we-tested-this" tabindex="-1">Why we tested this <a class="header-anchor" href="#why-we-tested-this" aria-label="Permalink to &quot;Why we tested this&quot;">​</a></h2><p>OpenAI Agents Python merged <a href="https://github.com/openai/openai-agents-python/pull/5066" target="_blank" rel="noreferrer">PR #5066</a> on September 17, 2026, then released v0.22.3. Maintainer Kazuhiro Sera explained that conditional approval callbacks could inspect arguments different from those used by the Python function. The new version prepares arguments first and requires manual approval when validation changes them.</p><p>The change turns an abstract governance concern into a testable path: raw JSON enters a tool, a schema interprets it, a policy decides, and a function creates an effect. Which representation reaches each stage?</p><p>We compared v0.22.2 and v0.22.3 instead of relying only on the fix description.</p><h2 id="six-cases-through-the-real-runner-path" tabindex="-1">Six cases through the real runner path <a class="header-anchor" href="#six-cases-through-the-real-runner-path" aria-label="Permalink to &quot;Six cases through the real runner path&quot;">​</a></h2><p>We pinned v0.22.2 at commit <code>83c737f</code> and v0.22.3 at <code>fdf21db</code>. Every case used the original <code>Runner</code>, decorated function tools, <code>ScriptedModel</code>, and tool execution path.</p><p>No live model or external write was involved. The probe recorded the callback input, whether manual approval interrupted the run, and the value received by the function body.</p><table tabindex="0"><thead><tr><th>Case</th><th>Raw arguments</th><th>Prepared arguments</th></tr></thead><tbody><tr><td>Unchanged safe target</td><td><code>{&quot;target&quot;:&quot;safe&quot;}</code></td><td>Unchanged</td></tr><tr><td>Unchanged protected target</td><td><code>{&quot;target&quot;:&quot;protected&quot;}</code></td><td>Unchanged</td></tr><tr><td>Omitted protected default</td><td><code>{}</code></td><td><code>{&quot;target&quot;:&quot;protected&quot;}</code></td></tr><tr><td>Explicit integer</td><td><code>{&quot;count&quot;:1}</code></td><td>Unchanged</td></tr><tr><td>String-to-integer coercion</td><td><code>{&quot;count&quot;:&quot;1&quot;}</code></td><td><code>{&quot;count&quot;:1}</code></td></tr><tr><td>Application validator</td><td><code>{&quot;environment&quot;:&quot;PROD&quot;}</code></td><td><code>{&quot;environment&quot;:&quot;prod&quot;}</code></td></tr></tbody></table><h2 id="approval-and-execution-could-diverge-in-v0-22-2" tabindex="-1">Approval and execution could diverge in v0.22.2 <a class="header-anchor" href="#approval-and-execution-could-diverge-in-v0-22-2" aria-label="Permalink to &quot;Approval and execution could diverge in v0.22.2&quot;">​</a></h2><p>Unchanged inputs behaved as expected: the safe target ran, while the protected target interrupted for approval.</p><p>The three transformed inputs exposed the gap:</p><ul><li>The conditional callback saw <code>{}</code> and allowed it; the function executed with the default <code>protected</code> target.</li><li>The callback saw string <code>&quot;1&quot;</code>; the function received integer <code>1</code>.</li><li>The callback saw <code>PROD</code>; the function received validator output <code>prod</code>.</li></ul><p>The conditional callback did not inspect the complete object consumed by the function.</p><p><img src="'+l+'" alt="Different handling of prepared arguments in v0.22.2 and v0.22.3"></p><p><em>Figure 1: v0.22.2 lets the callback inspect raw input while the function consumes prepared input. v0.22.3 routes changed values to manual approval. The figure summarizes our six cases, not every possible schema behavior.</em></p><h2 id="the-new-version-draws-a-conservative-boundary" tabindex="-1">The new version draws a conservative boundary <a class="header-anchor" href="#the-new-version-draws-a-conservative-boundary" aria-label="Permalink to &quot;The new version draws a conservative boundary&quot;">​</a></h2><p>In v0.22.3, unchanged arguments keep the prior conditional behavior. The safe target runs, and the protected target interrupts. Defaults, coercion, and application-level transformation all cause a manual approval interruption before the function executes.</p><p>This is more careful than merely moving the callback after validation. Sending transformed values into an existing callback could silently change an application&#39;s policy semantics. The new rule is: <strong>use the existing conditional policy only when raw and prepared arguments can be shown to remain equivalent; otherwise return the decision to a person.</strong></p><p>We also ran the new upstream approval-argument test file in v0.22.3: all 108 tests passed.</p><h2 id="approving-a-tool-name-is-not-enough" tabindex="-1">Approving a tool name is not enough <a class="header-anchor" href="#approving-a-tool-name-is-not-enough" aria-label="Permalink to &quot;Approving a tool name is not enough&quot;">​</a></h2><p>A verifiable approval needs at least four answers:</p><ol><li>Which representation did the person or policy inspect?</li><li>Had schema defaults and validators already run?</li><li>Did the arguments still match the approved object immediately before execution?</li><li>After resuming a session, is the system continuing the same prepared action?</li></ol><p>A dialog that says only “Allow deploy” does not tell the user whether the environment is raw <code>PROD</code>, normalized <code>prod</code>, or a default that was absent from the request. A stronger receipt binds authorization to a reproducible digest of the final action and invalidates the authorization when that action changes.</p><h2 id="does-codeflowmu-need-a-change" tabindex="-1">Does CodeFlowMu need a change? <a class="header-anchor" href="#does-codeflowmu-need-a-change" aria-label="Permalink to &quot;Does CodeFlowMu need a change?&quot;">​</a></h2><p>We inspected CodeFlowMu v2.1.2. Its approval service hashes a stable operation request, recomputes the digest before execution, and marks changed requests <code>stale</code>. It also binds an operation fingerprint, project, agent, task, thread, and role, and uses a one-time execution token. All 28 targeted approval-boundary tests passed.</p><p>Our development-review decision is therefore <strong>do not implement a new change this round</strong>. We found no local evidence of an approval/execution mismatch. The result belongs in the article and future review checklist; research evidence does not automatically become a development task.</p><h2 id="questions-the-fix-leaves-open" tabindex="-1">Questions the fix leaves open <a class="header-anchor" href="#questions-the-fix-leaves-open" aria-label="Permalink to &quot;Questions the fix leaves open&quot;">​</a></h2><ul><li>Should approval interfaces show only prepared arguments, or show raw input and a transformation diff?</li><li>Can prepared values be reproduced when a validator depends on time, external state, or arbitrary application code?</li><li>On resume, should a runtime prepare and compare again, or execute a saved prepared snapshot?</li><li>If objects cannot be compared safely, is mandatory human approval sufficient, or should execution be refused?</li></ul><p>For a non-specialist, the test is simpler: <strong>after you click “approve,” can you state exactly which values the program will use and what it will do?</strong> If not, the approval is still a button rather than execution evidence.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><ul><li><a href="https://github.com/openai/openai-agents-python/pull/5066" target="_blank" rel="noreferrer">OpenAI Agents Python PR #5066</a></li><li><a href="https://github.com/openai/openai-agents-python/releases/tag/v0.22.3" target="_blank" rel="noreferrer">v0.22.3 release</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-18-context-authority" target="_blank" rel="noreferrer">Public experiment record</a></li></ul>',36))])}const w=r(c,[["render",p]]);export{b as __pageData,w as default};
